/* ------------------------------------------------------------------ by language */
static const char *col(int lang, const char *pt, const char *es) { const char *s = lang == LANG_PT ? pt : lang == LANG_ES ? es : NULL; return s && *s ? s : NULL; }
const char *charsel_lang_rocker(int lang, const char *name) { for (size_t i = 0; name && i < sizeof ROCKER / sizeof *ROCKER; i++) if (!strcasecmp(ROCKER[i].name, name)) return col(lang, ROCKER[i].pt, ROCKER[i].es); return NULL; }
const char *charsel_lang_guitar(int lang, uint32_t id) { for (size_t i = 0; i < sizeof GUITAR / sizeof *GUITAR; i++) if (GUITAR[i].id == id) return col(lang, GUITAR[i].pt, GUITAR[i].es); return NULL; }
const char *charsel_lang_name(int lang, int kind, const char *en) {
    const char *const (*t)[3] = kind == CS_PT_OUTFIT ? OUTFIT : kind == CS_PT_STYLE ? STYLE : kind == CS_PT_FINISH ? FINISH : kind == CS_PT_LINE ? LINE : MAKER;
    for (int i = 0; en && t[i][0]; i++) if (!strcasecmp(t[i][0], en)) return col(lang, t[i][1], t[i][2]); return NULL;
}
/* charsel.h's, in the language chosen */
const char *charsel_pt_rocker(const char *name) { return charsel_lang_rocker(lang_get(), name); }
const char *charsel_pt_guitar(uint32_t id) { return charsel_lang_guitar(lang_get(), id); }
const char *charsel_pt_name(int kind, const char *en) { const char *s = charsel_lang_name(lang_get(), kind, en); return s ? s : en; }
